n.exploreUrl:
@js:
let ck = String(cookie.getCookie("fanqienovel.com").match(/sessionid=([^;]*)/)?.[1] || '');  

let type = ["番茄小说"];  
let 番茄小说 = ["书架", "都市", "探案", "历史", "异界", "游戏", "奥特", "万界", "盗墓", "明星", "动漫", "脑洞", "灵异", "悬疑", "玄幻", "仙侠", "无敌", "大秦", "明朝", "三国", "大唐", "宋朝", "清朝", "推理", "鉴宝", "海贼", "武将", "国运", "乡村", "洪荒", "空间", "群聊"];  

JSON.stringify(  
    type.reduce((arr, x) => {  
        arr.push({  
            title: x,  
            url: "",  
            style: { layout_flexBasisPercent: 1 }  
        });  
        eval(x).forEach(k => {  
            arr.push({  
                title: k,  
                url: `{{source.bookSourceUrl}}syfx?lx=${x}&ck=${ck}&fl=${k}&page={{page}}`,  
                style: { layout_flexBasisPercent: 0.2 }  
            });  
        });  
        return arr;  
    }, [])  
);

ruleContent.content:
@js:
function processContent() {  

    let content = JSON.parse(result).data.content;  
    let md5Matches = content.matchAll(/"md5":"([a-f0-9]+)"/g);  
    let md5Values = Array.from(md5Matches, match => match[1]); 

    if (md5Values.length === 0) {  
        return content;  
    }  

    let imgTags = md5Values.map(md5 => `<img src="https://p6-novel.byteimg.com/origin/novel-pic/${md5}" >`);  
    return imgTags.join('');  
}  
processContent();

